// writeJournal writes named files into a fresh temp dir and returns the path of the first.
func writeJournal(t *testing.T, files map[string]string, main string) string {
	t.Helper()
	dir := t.TempDir()
	for name, body := range files {
		path := filepath.Join(dir, name)
