package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

// Amount is a quantity of a commodity, scaled by scale to avoid float error.
type Amount struct {
	Val  int64
	Comm string
}

const scale = 100000000 // 1e8

// Posting is one account line of a transaction.
type Posting struct {
	Account string
	Amount  Amount
	Line    int
}

// Transaction is a dated entry with its postings.
type Transaction struct {
	Date     string
	Payee    string
	Postings []Posting
	Line     int
	File     string
}

// Journal is a parsed ledger file, includes flattened in.
type Journal struct {
	Transactions []Transaction
}

// ParseFile reads path (following include directives) into a Journal.
func ParseFile(path string) (*Journal, error) {
	j := &Journal{}
	if err := parseInto(j, path); err != nil {
		return nil, err
	}
	return j, nil
}

func parseInto(j *Journal, path string) error {
	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("%s: %v", path, err)
	}
	defer f.Close()

	sc := bufio.NewScanner(f)
	lineNo := 0
	var cur *Transaction
	for sc.Scan() {
		lineNo++
		raw := sc.Text()
		line := strings.TrimRight(stripComment(raw), " \t")
		if strings.TrimSpace(line) == "" {
			cur = nil
			continue
		}
		indented := line[0] == ' ' || line[0] == '\t'
		if !indented {
			date, payee, err := parseHeader(line)
			if err != nil {
				return fmt.Errorf("%s:%d: %v", path, lineNo, err)
			}
			j.Transactions = append(j.Transactions, Transaction{Date: date, Payee: payee, Line: lineNo, File: path})
			cur = &j.Transactions[len(j.Transactions)-1]
			continue
		}
		if cur == nil {
			return fmt.Errorf("%s:%d: posting outside of any transaction", path, lineNo)
		}
		p, err := parsePosting(strings.TrimSpace(line))
		if err != nil {
			return fmt.Errorf("%s:%d: %v", path, lineNo, err)
		}
		p.Line = lineNo
		cur.Postings = append(cur.Postings, p)
	}
	return sc.Err()
}

func stripComment(line string) string {
	if i := strings.IndexByte(line, ';'); i >= 0 {
		return line[:i]
	}
	return line
}

func parseHeader(line string) (date, payee string, err error) {
	parts := strings.SplitN(line, " ", 2)
	date = parts[0]
	if err := checkDate(date); err != nil {
		return "", "", err
	}
	if len(parts) == 2 {
		payee = strings.TrimSpace(parts[1])
	}
	return date, payee, nil
}

func checkDate(s string) error {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return fmt.Errorf("malformed date %q, want YYYY-MM-DD", s)
	}
	for i, c := range s {
		if i == 4 || i == 7 {
			continue
		}
		if c < '0' || c > '9' {
			return fmt.Errorf("malformed date %q, want YYYY-MM-DD", s)
		}
	}
	return nil
}

// parsePosting splits "account  -42.50 USD" on two-or-more spaces (or a tab).
func parsePosting(line string) (Posting, error) {
	account, amountText := splitPosting(line)
	if account == "" {
		return Posting{}, fmt.Errorf("posting has no account name")
	}
	p := Posting{Account: account}
	if amountText == "" {
		return p, nil
	}
	amt, err := parseAmount(amountText)
	if err != nil {
		return Posting{}, err
	}
	p.Amount = amt
	return p, nil
}

func splitPosting(line string) (account, amount string) {
	if i := strings.Index(line, "\t"); i >= 0 {
		return strings.TrimSpace(line[:i]), strings.TrimSpace(line[i+1:])
	}
	if i := strings.Index(line, "  "); i >= 0 {
		return strings.TrimSpace(line[:i]), strings.TrimSpace(line[i+2:])
	}
	return strings.TrimSpace(line), ""
}

func parseAmount(s string) (Amount, error) {
	fields := strings.Fields(s)
	if len(fields) != 2 {
		return Amount{}, fmt.Errorf("malformed amount %q, want e.g. -42.50 USD", s)
	}
	val, err := parseDecimal(fields[0])
	if err != nil {
		return Amount{}, err
	}
	return Amount{Val: val, Comm: fields[1]}, nil
}

func parseDecimal(s string) (int64, error) {
	bad := fmt.Errorf("malformed number %q", s)
	neg := false
	body := s
	if strings.HasPrefix(body, "-") {
		neg, body = true, body[1:]
	} else if strings.HasPrefix(body, "+") {
		body = body[1:]
	}
	intPart, fracPart := body, ""
	if i := strings.IndexByte(body, '.'); i >= 0 {
		intPart, fracPart = body[:i], body[i+1:]
	}
	if intPart == "" && fracPart == "" {
		return 0, bad
	}
	if len(fracPart) > 8 {
		return 0, fmt.Errorf("number %q has more than 8 decimal places", s)
	}
	var val int64
	for _, c := range intPart + fracPart {
		if c < '0' || c > '9' {
			return 0, bad
		}
		val = val*10 + int64(c-'0')
	}
	for i := len(fracPart); i < 8; i++ {
		val *= 10
	}
	if neg {
		val = -val
	}
	return val, nil
}
