func run(args []string, stdout, stderr io.Writer) int {
	if len(args) < 2 {
		fmt.Fprintln(stderr, "usage: ledger <validate|balance|register> <file> [options]")
		return 2
	}
	cmd, path := args[0], args[1]
	switch cmd {
	case "validate":
		if _, err := ParseFile(path); err != nil {
			fmt.Fprintln(stderr, "ledger:", err)
			return 1
		}
		return 0
	default:
		fmt.Fprintf(stderr, "ledger: unknown command %q\n", cmd)
		return 2
	}
}
