// Residual is the non-zero per-commodity sum of the transaction's postings,
// ordered by commodity. An empty result means the transaction balances.
func (t Transaction) Residual() []Amount {
	sums := map[string]int64{}
	var order []string
	for _, p := range t.Postings {
		if _, seen := sums[p.Amount.Comm]; !seen {
			order = append(order, p.Amount.Comm)
		}
		sums[p.Amount.Comm] += p.Amount.Val
	}
	sort.Strings(order)
	var out []Amount
	for _, c := range order {
		if sums[c] != 0 {
			out = append(out, Amount{Val: sums[c], Comm: c})
		}
	}
	return out
}

// String renders an amount with at least two decimal places, e.g. "-42.50 USD".
func (a Amount) String() string {
	val, sign := a.Val, ""
	if val < 0 {
		val, sign = -val, "-"
	}
	frac := fmt.Sprintf("%08d", val%scale)
	for len(frac) > 2 && frac[len(frac)-1] == '0' {
		frac = frac[:len(frac)-1]
	}
	s := fmt.Sprintf("%s%d.%s", sign, val/scale, frac)
	if a.Comm != "" {
		s += " " + a.Comm
	}
	return s
}

func joinAmounts(as []Amount) string {
	parts := make([]string, len(as))
	for i, a := range as {
		parts[i] = a.String()
	}
	return strings.Join(parts, ", ")
}
