package main

import (
	"fmt"
	"io"
	"sort"
	"strings"
)

// balances sums every posting into its own account.
func balances(j *Journal) map[string]map[string]int64 {
	acc := map[string]map[string]int64{}
	for _, t := range j.Transactions {
		for _, p := range t.Postings {
			if acc[p.Account] == nil {
				acc[p.Account] = map[string]int64{}
			}
			acc[p.Account][p.Amount.Comm] += p.Amount.Val
		}
	}
	return acc
}

// accountTree returns every account and parent account, sorted by segment.
func accountTree(acc map[string]map[string]int64) []string {
	seen := map[string]bool{}
	for name := range acc {
		segs := strings.Split(name, ":")
		for i := range segs {
			seen[strings.Join(segs[:i+1], ":")] = true
		}
	}
	nodes := make([]string, 0, len(seen))
	for name := range seen {
		nodes = append(nodes, name)
	}
	sort.Strings(nodes)
	return nodes
}

// subtreeTotal sums an account and everything below it.
// ponytail: O(accounts^2); fine for journal-sized input.
func subtreeTotal(acc map[string]map[string]int64, node string) []Amount {
	sums := map[string]int64{}
	for name, comms := range acc {
		if name != node && !strings.HasPrefix(name, node+":") {
			continue
		}
		for c, v := range comms {
			sums[c] += v
		}
	}
	var out []Amount
	for c, v := range sums {
		if v != 0 {
			out = append(out, Amount{Val: v, Comm: c})
		}
	}
	sort.Slice(out, func(i, k int) bool { return out[i].Comm < out[k].Comm })
	return out
}

func reportBalance(j *Journal, stdout io.Writer, depth int) int {
	acc := balances(j)
	for _, node := range accountTree(acc) {
		segs := strings.Split(node, ":")
		if depth > 0 && len(segs) > depth {
			continue
		}
		total := subtreeTotal(acc, node)
		if len(total) == 0 {
			continue
		}
		label := strings.Repeat("  ", len(segs)-1) + segs[len(segs)-1]
		fmt.Fprintf(stdout, "%-30s%10s\n", label, joinAmounts(total))
	}
	return 0
}
